import csv
from decimal import Decimal
from pathlib import Path

FX_DIR = Path(__file__).resolve().parent / "fixtures" / "fx"


def load_rates(day):
    """Return {currency: Decimal rate against USD} for a day in usd-YYYY-MM.csv."""
    with open(FX_DIR / f"usd-{day[:7]}.csv", newline="") as f:
        for row in csv.DictReader(f):
            if row["Date"] == day:
                return {code: Decimal(rate) for code, rate in row.items() if code != "Date"}
    raise KeyError(f"no rates for {day}")

